CREATE TABLE IF NOT EXISTS loans (id uuid PRIMARY KEY, customer_id uuid NOT NULL REFERENCES customers(id), loan_ref text UNIQUE NOT NULL, product text NOT NULL, status text NOT NULL, principal numeric(14,2) NOT NULL, outstanding numeric(14,2) NOT NULL, overdue numeric(14,2) NOT NULL DEFAULT 0, started_on date NOT NULL, closed_on date);
CREATE TABLE IF NOT EXISTS loan_transactions (id uuid PRIMARY KEY, loan_id uuid NOT NULL REFERENCES loans(id), collection_date date NOT NULL, target numeric(14,2) NOT NULL, collection numeric(14,2) NOT NULL, overdue numeric(14,2) NOT NULL DEFAULT 0, status text NOT NULL);
CREATE TABLE IF NOT EXISTS savings_transactions (id uuid PRIMARY KEY, customer_id uuid NOT NULL REFERENCES customers(id), transaction_date date NOT NULL, own_savings numeric(14,2) NOT NULL, security numeric(14,2) NOT NULL DEFAULT 0, withdrawal numeric(14,2) NOT NULL DEFAULT 0, balance numeric(14,2) NOT NULL);
CREATE TABLE IF NOT EXISTS financial_assessments (id uuid PRIMARY KEY, application_id uuid NOT NULL REFERENCES applications(id), application_version integer NOT NULL, monthly_income numeric(14,2) NOT NULL, monthly_expense numeric(14,2) NOT NULL, external_debt numeric(14,2) NOT NULL DEFAULT 0, proposed_amount numeric(14,2) NOT NULL, proposed_term_months integer NOT NULL, proposed_installment numeric(14,2) NOT NULL, monthly_surplus numeric(14,2) NOT NULL, created_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(application_id, application_version));
CREATE TABLE IF NOT EXISTS application_checklists (id uuid PRIMARY KEY, application_id uuid NOT NULL REFERENCES applications(id), application_version integer NOT NULL, checklist_type text NOT NULL, items jsonb NOT NULL DEFAULT '[]'::jsonb, remarks text, updated_by uuid NOT NULL REFERENCES users(id), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(application_id, application_version, checklist_type));
